export const initialVocabulary: Word[] = rawVocabulary.map(item => ({
  ...item,
  // options / sentenceOptions は scripts/bake_options.ts で事前生成済み。
  // 以前はここで読み込みのたびに 7,753語ぶんをランダム生成しており、
  // 誤答が同レベルからの無作為抽出（品詞すら揃わない）になっていた。
  options: Array.isArray(item.options) && item.options.length >= 2
    ? item.options
    : [item.translation],
  sentenceOptions: Array.isArray(item.sentenceOptions) && item.sentenceOptions.length >= 2
    ? item.sentenceOptions
    : [item.word]
})) as Word[];
